export type PresentationRequest = {
    /**
     * Webhook configuration to receive the response.
     * If not provided, the configured webhook from the configuration will be used.
     */
    webhook?: WebhookConfig & {
        /**
         * The URL to which the webhook will send notifications.
         */
        url?: string;
        /**
         * Webhook authentication strategy.
         */
        auth?: {
            /**
             * Disable authentication.
             */
            type: 'none';
        } | {
            /**
             * Use API key authentication.
             */
            type: 'apiKey';
            /**
             * API key authentication settings.
             */
            config: {
                /**
                 * The header name used to send the API key.
                 */
                headerName: string;
                /**
                 * The API key value.
                 */
                value: string;
            };
        };
        /**
         * List of credential IDs to include raw tokens for (for example ['sca_credential']).
         */
        includeRawTokensFor?: Array<string>;
    };
    /**
     * Optional transaction data to include in the OID4VP request.
     * If provided, this will override the transaction_data from the presentation configuration.
     */
    transaction_data?: Array<{
        /**
         * Transaction data type identifier.
         */
        type: string;
        /**
         * Credential query ids this transaction data applies to.
         */
        credential_ids: Array<string>;
        /**
         * Transaction details. Required for TS12 SCA transaction data.
         */
        payload?: unknown;
        [key: string]: unknown;
    }>;
    /**
     * Client identifier scheme for the OID4VP request. Defaults to x509_hash.
     */
    clientIdScheme?: 'x509_hash' | 'x509_san_dns' | 'openid_federation';
    /**
     * The type of response expected from the presentation request.
     */
    response_type: 'uri' | 'dc-api' | 'iso-18013-7';
    /**
     * Identifier of the presentation configuration
     */
    requestId: string;
    /**
     * Optional redirect URI to which the user-agent should be redirected after the presentation is completed.
     * You can use the `{sessionId}` placeholder in the URI, which will be replaced with the actual session ID.
     */
    redirectUri?: string;
    /**
     * Origin of the page that calls the Digital Credentials API (`dc-api`,
     * `iso-18013-7`). Required for these response types unless
     * `allowedOrigins` of the presentation configuration lists exactly one
     * origin; must be one of `allowedOrigins` when they are set. Set it from
     * your own configuration, never from end-user input such as a forwarded
     * `Origin` header.
     * Example: "https://shop.example"
     */
    expected_origin?: string;
    /**
     * Optional clock skew tolerance for this presentation offer, in seconds.
     * If provided, this overrides the presentation configuration for the created session.
     */
    skewSeconds?: number;
    /**
     * Caller reference stored with the session, e.g. an order or case id.
     * Stored in plaintext and kept on anonymization: never put personal data here.
     */
    reference?: string;
};

